var o=`0417-soda-bread`;var i=`world-0417`;var t=`IE`;var a=`northern-europe`;var r=8;var l=61;var d={en:`Soda Bread`,ua:`Содовий хліб`};var s={en:`A traditional dish from Ireland, centered on all-purpose flour, whole wheat flour, baking soda, buttermilk. A measured home-kitchen version organized by cooking step.`,ua:`Традиційна страва кухні країни Ірландія. Основні складники: пшеничне борошно універсальне, цільнозернове пшеничне борошно, харчова сода, сколотини. Домашній варіант із кількостями продуктів за етапами приготування.`};var u=[{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:7,i:[[`all-purpose-flour`,450,`g`],[`whole-wheat-flour`,150,`g`],[`baking-soda`,8,`g`],[`table-salt`,8,`g`]]},{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:3,i:[[`buttermilk`,500,`ml`]]},{en:`Roll or press the prepared dough evenly into the desired thickness and shape.`,ua:`Розкачайте або розпластайте підготовлене тісто рівномірним шаром потрібної товщини та форми.`,t:[`pressing`,`rolling-out-dough`],m:6,i:[]},{en:`Bake in a preheated 180°C oven for about 45 minutes until set, golden and cooked through. Cool on a rack.`,ua:`Випікайте в розігрітій до 180°C духовці приблизно 45 хвилин до рум’яності та повної готовності. Остудіть на решітці.`,t:[`baking`],m:45,i:[]}];var g={slug:o,id:i,country:`IE`,region:a,servings:8,minutes:61,title:d,text:s,steps:u};export{t as country,g as default,i as id,l as minutes,a as region,r as servings,o as slug,u as steps,s as text,d as title};